var schemeName = Tama.Args.Get(args, "scheme", "");
var targetTitle = Tama.Args.Get(args, "target", "");
Document target = null;
foreach (Document d in app.Documents) if (!d.IsLinked && d.Title == targetTitle) target = d;
if (target == null) throw new InvalidOperationException("The target model is not open: " + targetTitle);
return new FilteredElementCollector(target).OfCategory(BuiltInCategory.OST_Areas).WhereElementIsNotElementType().Cast<Autodesk.Revit.DB.Area>()
 .Where(a => a.AreaScheme != null && a.AreaScheme.Name == schemeName && WorksharingUtils.GetCheckoutStatus(target, a.Id) == CheckoutStatus.OwnedByOtherUser)
 .GroupBy(a => (a.Level?.Name ?? "-") + " | owner: " + WorksharingUtils.GetWorksharingTooltipInfo(target, a.Id).Owner)
 .Select(g => new { key = g.Key, count = g.Count() }).ToList();
